import React, { useState, useEffect, useRef } from 'react';
import axios from 'axios';

const SeriesAIChatbot = () => {
  const [messages, setMessages] = useState([
    {
      role: 'assistant',
      content: 'Merhaba! Ben dizi önerileri konusunda size yardımcı olabilirim. Hangi tür dizileri seviyorsunuz?'
    }
  ]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const messagesEndRef = useRef(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!input.trim()) return;

    const userMessage = input.trim();
    setInput('');
    setMessages(prev => [...prev, { role: 'user', content: userMessage }]);
    setIsLoading(true);

    try {
      // Hugging Face API'ye istek gönder
      const response = await axios.post(
        'https://api-inference.huggingface.co/models/facebook/blenderbot-400M-distill',
        {
          inputs: userMessage,
          options: {
            wait_for_model: true
          }
        },
        {
          headers: {
            'Authorization': 'Bearer hf_xxx', // Hugging Face API anahtarınızı buraya ekleyin
            'Content-Type': 'application/json'
          }
        }
      );

      // API yanıtını kontrol et
      if (response.data && response.data.generated_text) {
        setMessages(prev => [...prev, { role: 'assistant', content: response.data.generated_text }]);
      } else {
        // API yanıt vermezse veya hata verirse fallback yanıtı kullan
        const fallbackResponse = generateFallbackResponse(userMessage);
        setMessages(prev => [...prev, { role: 'assistant', content: fallbackResponse }]);
      }
    } catch (error) {
      console.error('API hatası:', error);
      // Hata durumunda fallback yanıtı kullan
      const fallbackResponse = generateFallbackResponse(userMessage);
      setMessages(prev => [...prev, { role: 'assistant', content: fallbackResponse }]);
    } finally {
      setIsLoading(false);
    }
  };

  const generateFallbackResponse = (userMessage) => {
    const lowerMessage = userMessage.toLowerCase();
    
    if (lowerMessage.includes('aksiyon') || lowerMessage.includes('macera')) {
      return 'Aksiyon dizileri için "The Witcher", "Game of Thrones" ve "The Last Kingdom" önerebilirim.';
    } else if (lowerMessage.includes('dram') || lowerMessage.includes('duygusal')) {
      return 'Dram dizileri için "This Is Us", "The Crown" ve "Breaking Bad" harika seçenekler olabilir.';
    } else if (lowerMessage.includes('komedi') || lowerMessage.includes('güldürü')) {
      return 'Komedi dizileri için "The Office", "Brooklyn Nine-Nine" ve "Friends" klasikleşmiş dizilerdir.';
    } else if (lowerMessage.includes('bilim kurgu') || lowerMessage.includes('sci-fi')) {
      return 'Bilim kurgu dizileri için "Stranger Things", "Black Mirror" ve "The Expanse" önerebilirim.';
    } else if (lowerMessage.includes('gerilim') || lowerMessage.includes('thriller')) {
      return 'Gerilim dizileri için "Mindhunter", "True Detective" ve "Dark" mükemmel seçeneklerdir.';
    } else {
      return 'Size daha iyi önerilerde bulunabilmem için hangi tür dizileri sevdiğinizi belirtebilir misiniz? Örneğin: aksiyon, dram, komedi, bilim kurgu veya gerilim?';
    }
  };

  return (
    <div className="bg-white/90 backdrop-blur-sm rounded-xl shadow-lg overflow-hidden">
      <div className="p-4 bg-gradient-to-r from-purple-600 to-pink-600">
        <h2 className="text-xl font-bold text-white">Dizi Öneri Asistanı</h2>
      </div>
      
      <div className="h-96 overflow-y-auto p-4 space-y-4">
        {messages.map((message, index) => (
          <div
            key={index}
            className={`flex ${message.role === 'user' ? 'justify-end' : 'justify-start'}`}
          >
            <div
              className={`max-w-[80%] rounded-lg p-3 ${
                message.role === 'user'
                  ? 'bg-purple-600 text-white'
                  : 'bg-gray-100 text-gray-800'
              }`}
            >
              {message.content}
            </div>
          </div>
        ))}
        {isLoading && (
          <div className="flex justify-start">
            <div className="bg-gray-100 text-gray-800 rounded-lg p-3">
              Düşünüyorum...
            </div>
          </div>
        )}
        <div ref={messagesEndRef} />
      </div>

      <form onSubmit={handleSubmit} className="p-4 border-t">
        <div className="flex space-x-2">
          <input
            type="text"
            value={input}
            onChange={(e) => setInput(e.target.value)}
            placeholder="Dizi önerileri için bir soru sorun..."
            className="flex-1 p-2 border rounded-lg focus:outline-none focus:ring-2 focus:ring-purple-600"
          />
          <button
            type="submit"
            disabled={isLoading}
            className="px-4 py-2 bg-gradient-to-r from-purple-600 to-pink-600 text-white rounded-lg hover:from-purple-700 hover:to-pink-700 focus:outline-none focus:ring-2 focus:ring-purple-600 disabled:opacity-50"
          >
            Gönder
          </button>
        </div>
      </form>
    </div>
  );
};

export default SeriesAIChatbot;
